});

var jsonData = pm.response.json();
pm.collectionVariables.set('usersExist', true);

pm.test("There are users to authenticate", function () {
    pm.expect(jsonData.users.length).gt(0);
})

const user = jsonData.users.find(usr => usr.username.length > 0 && usr.password.length > 0);

pm.test("A user with valid credentials was found", function () {
    pm.expect(user, "No user with username+password found").to.not.be.undefined;
});

if (user != undefined) {
    pm.collectionVariables.set('userName', user.username);
    pm.collectionVariables.set('userPassword', user.password);
    pm.collectionVariables.set('userId', user.id);
}
else
    pm.collectionVariables.set('usersExist', false);

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

var jsonData = pm.response.json();

pm.test("Access token is returned", function () {
    pm.expect(jsonData.accessToken).to.not.be.null;
});

pm.collectionVariables.set('token', jsonData.accessToken);

if (!pm.collectionVariables.get("usersExist")) {
    pm.test.skip('Token test skipped due to missing user and password');
    pm.execution.skipRequest();
}

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

const { products } = pm.response.json();

pm.test("Products list is not empty", function () {
    pm.expect(products).to.be.an("array").that.is.not.empty;
});

pm.collectionVariables.unset('productId');
pm.collectionVariables.unset('existingIds');

if (products.length > 0) {
    const product = products.find(pr => pr.id != undefined && pr.id > 0);

    pm.test("At least one product has a valid ID", () => {
        pm.expect(product, "No product with a valid ID found").to.exist;
    });

    if (product) {
        pm.collectionVariables.set('productId', product.id);
        pm.collectionVariables.set('existingIds', JSON.stringify(products.slice(0, 3).map(p => p.id)));
    }
}

const existingIdsRaw = pm.collectionVariables.get('existingIds');

if (!existingIdsRaw) {
    pm.test('There are products to add to Cart', function () {
        throw new Error('There are no products to add to Cart. Tests for creating a cart of Products did not run!');
    });
    pm.execution.skipRequest();
} else {
    pm.test('There are products to add to Cart', function () {
        pm.expect(existingIdsRaw, 'There should be item ids to add to Cart').to.not.be.undefined;
    });

    const ids = JSON.parse(existingIdsRaw);
    const products = ids.map(id => ({
        id,
        quantity: Number(pm.variables.replaceIn('{{$randomInt}}'))
    }));

    pm.collectionVariables.set('listProducts', JSON.stringify(products));
}

pm.test("Response is successful", function () {
    pm.response.to.have.status(201);
});

pm.test("Response has valid format", function () {
    pm.response.to.be.json;
});

var { products } = pm.response.json();

const ids = JSON.parse(pm.collectionVariables.get('existingIds'));

pm.test(`${ids.length} products have been added`, function () {
    pm.expect(products.length).to.eql(ids.length);
});

pm.test('Response contains expected values', function () {
    products.forEach(product => {
        pm.expect(product, 'Product should have id').to.have.property('id');
        pm.expect(product,'Product should have quantity').to.have.property('quantity');
    });
});

pm.test("All items have been added", function () {
    const addedProducts = JSON.parse(pm.collectionVariables.get('listProducts'));

    addedProducts.forEach((item) => {
        const match = products.find(p => p.id === item.id);
        pm.expect(match).to.include(item);
    });
});

